-- Gerado por ferramentas/docx_para_sql.py — etapa 2, parte 1 de 8
-- Pode ser executado mais de uma vez; as partes podem ser executadas em qualquer ordem.
begin;
do $$ begin if (select count(*) from encontros where etapa_id=(select id from etapas where numero=2)) <> 35 then raise exception 'A etapa 2 não tem 35 encontros no banco — a atualização por ordem não é segura.'; end if; end $$;
update encontros set conteudo_html='<p><strong>Palavra inicial:</strong> O objetivo da celebração é apresentar a toda a comunidade os catequistas que exercerão o ministério da catequese, destacando a grande importância desse serviço para a vida da Igreja. Aconselhamos que essa celebração aconteça no 1º Domingo do Advento seguindo a liturgia do dia. Por motivos pastorais pode ocorrer num outro dia da semana.</p> <p><strong>Preparando o ambiente:</strong> Cartaz ou banner com o Calendário Litúrgico que poderá entrar na procissão inicial e ser colocado em lugar de destaque. Bíblia para ser entregue uma para cada catequista, em sinal da missão por eles assumida como anunciadores do Reino. Reservar bancos para os catequistas. Acrescente-se na monição inicial a apresentação e envio dos catequistas.</p> <p>Procissão inicial: Os catequistas participam da procissão inicial.</p> <p>Saudação inicial: O presidente acolhe os catequistas. (Tudo segue como de costume, até a homilia).</p> <p>Rito de apresentação e envio dos catequistas</p> <p>Após a proclamação do Evangelho e a homilia, o diácono, ou na falta dele o coordenador da catequese, chama cada um dos catequistas pelo nome.</p> <p>Diácono: Queiram aproximar-se os que exercerão o ministério da catequese: ...N..., ...N..., ...</p> <p>Cada um responde individualmente: <em>Presente!</em> (ou todos juntos, se forem muitos).</p> <p>Os catequistas proferem seu compromisso catequético e recebem o Livro Sagrado, a Bíblia, sinal do seu ministério. Todos os catequistas de pé e a uma só voz fazem seu compromisso:</p> <p>"Nós, catequistas, viemos, perante esta assembleia congregada pelo Senhor, manifestar o desejo de participarmos do ministério da catequese. O Senhor que nos chamou a formar parte do seu povo, pelo Batismo, convida-nos a sermos testemunhas, mestres e educadores da fé. Ao assumirmos este serviço, estamos conscientes de participarmos da grande missão que Jesus Cristo confiou à sua Igreja: ''Ide por todo o mundo e anunciai a todos a mensagem da salvação''."</p> <p>Presidente: Caros catequistas, quereis viver o vosso ministério de catequistas na fidelidade a Deus e na atenção aos irmãos?</p> <p>Catequistas: Sim, queremos.</p> <p>Presidente: Estais dispostos a desempenhar a vossa missão, sendo testemunhas da Boa-Nova de Jesus?</p> <p>Catequistas: Sim, estamos.</p> <p>Presidente: Quereis viver o vosso serviço de catequistas, em espírito de serviço à comunidade?</p> <p>Catequistas: Sim, queremos.</p> <p><em>(Impõe as mãos).</em></p> <p>Presidente: "Dignai-vos, Senhor, confirmar em seu propósito, com a vossa bênção † paterna, estes vossos filhos e filhas que anseiam por entregar-se ao trabalho da catequese, para que se esforcem por instruir os seus irmãos em tudo que aprenderem com a meditação da vossa Palavra de acordo com a doutrina da Igreja"¹.</p> <p>R. Amém.</p> <p>Logo após se aproximam, um de cada vez, ou, se forem muitos, fazem uma fila um do lado do outro, e o presidente entrega a Palavra de Deus a cada um, dizendo:</p> <p>Presidente: ...N..., recebe o Livro Sagrado, instrumento e sinal de seu ministério, exerça-o com solicitude, transmitindo com fidelidade a sua Palavra, para que ela frutifique cada vez mais no coração das pessoas.</p> <p>Catequista: Amém.</p> <p><em>(se forem muitos, o padre diz a fórmula somente uma vez, e depois prossegue com a entrega da Bíblia, enquanto se entoa um canto. Todos retornam aos seus lugares e a missa prossegue como de costume).</em></p> <p>Preces: No momento da Oração da Assembleia, pode-se acrescentar algumas das orações pelos catequistas e catequizandos. Se for oportuno, após a oração Pós-Comunhão, apresentam-se os catequizandos que ingressarão na catequese. No final o padre dá a bênção de envio aos catequistas.</p> <p>Oremos:</p> <p>Deus de infinita sabedoria, que chamastes o Apóstolo Paulo para anunciar às nações o vosso Filho, nós vos imploramos em favor de vossos servos e servas, catequistas de nossas comunidades, que vivem com dedicação e fidelidade sua vocação: concedei-lhes imitar o apóstolo dos gentios, abrindo-se a vossa graça, e considerando todas as coisas como perda comparada ao bem supremo do conhecimento de Cristo, vosso Filho, a fim de que permaneçam fiéis ao anúncio da Palavra e no testemunho da caridade. Amém.</p> <p>ABENÇOE-VOS DEUS TODO-PODEROSO, PAI...</p> <p>¹ Oração extraída do livro <em>Presbiteral</em> (Petrópolis: Vozes, 2007), "Bênçãos Referentes à Catequese e à Oração Comum", p. 671.</p>', preparo_html='<p>Cartaz ou banner com o Calendário Litúrgico que poderá entrar na procissão inicial e ser colocado em lugar de destaque. Bíblia para ser entregue uma para cada catequista, em sinal da missão por eles assumida como anunciadores do Reino. Reservar bancos para os catequistas. Acrescente-se na monição inicial a apresentação e envio dos catequistas.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=1; -- Celebração de Apresentação e Envio dos Catequistas
update encontros set conteudo_html='<p><em>(Encontro a ser realizado na semana que antecede a celebração de entrega da Profissão de Fé).</em></p> <p><strong>Palavra inicial:</strong> Prezados catequistas, nesta reunião queremos apresentar aos pais e padrinhos de Batismo uma visão geral de como será a celebração de entrega da Profissão de Fé. Primeiramente uma reflexão sobre a importância e significado e depois o desenrolar dos ritos.</p> <p><strong>Preparando o ambiente:</strong> Prever sala mais ampla para acomodar todos os participantes. Nesta sala providenciar: ambão com toalha da cor do Tempo Litúrgico, Bíblia, vela e flores. Em uma mesa: folhas com o credo que serão entregues aos catequizandos (sugerimos colocar as duas versões do Credo, uma paralela a outra: O Credo dos apóstolos e o niceno-constantinopolitano) e cópias com o roteiro da celebração.</p> <p><strong>Acolhida:</strong> O catequista acolhe os pais e padrinhos, dando-lhes boas-vindas e explicando o motivo da reunião. Logo após convida a todos a ficarem de pé e fazerem uma breve oração (se o tempo permitir poderá ser feita a "leitura orante" de um texto bíblico).</p> <p><strong>Oração inicial:</strong> Pode-se invocar o Espírito Santo com a oração "Vinde, Espírito Santo, enchei...", e fazer a leitura de um texto bíblico.</p> <p>Orientações para a reunião</p> <ul> <li><p>Primeiramente agradecer a presença dos pais e padrinhos e pedir para que se apresentem e digam se são pais ou padrinhos;</p></li> <li><p>Introduzir com uma breve explicação sobre o Tempo Litúrgico, principalmente o significado do Tempo do Advento (se a celebração acontecer nessa data);</p></li> <li><p>O catequista faz uma breve reflexão sobre a importância e significado da celebração dizendo que nela os catequizandos receberão os fundamentos da fé cristã, e, a partir de cada artigo impresso no Credo, irão meditar e aprofundar a fé que a Igreja nos dá;</p></li> <li><p>Mostrar a folha com o Credo impresso, o qual os catequizandos receberão, e mostrar que tem as duas versões mais usadas pela Igreja uma paralela a outra, e explicar que Símbolo dos Apóstolos foi uma das primeiras redações do Credo, é uma versão mais resumida. Com a necessidade, devido ao aumento das heresias, a Igreja o completou nos concílios de Niceia (325) e Constantinopla I (381), sendo assim conhecida a segunda versão como Credo niceno-constantinopolitano;</p></li> <li><p>Poderá rapidamente trabalhar o texto de São Cirilo de Jerusalém: "O símbolo da fé", disponível no Material de Apoio;</p></li> <li><p>Depois distribuir o roteiro da celebração e explicar passo a passo todo o desenrolar dos ritos;</p></li> <li><p>Orientá-los da importância de se rezar em família e de incentivar a leitura bíblica com os filhos;</p></li> <li><p>Poderá distribuir algumas funções: leitores dos textos bíblicos, oração da assembleia, apresentação das oferendas;</p></li> <li><p>Orientar para que as fotos e filmagens sejam discretas e não atrapalhem a participação da assembleia;</p></li> <li><p>Apresentar a hora e local da celebração e orientar para que procurem chegar com antecedência.</p></li> </ul> <p><strong>Oração final:</strong> O catequista convida a todos a rezar a oração do Pai-nosso e logo depois, de braços abertos, conclui com a oração:</p> <p>Deus Pai de bondade, fazei que estes pais e padrinhos possam ser verdadeiros exemplos de sua Palavra aos seus filhos e afilhados. Que eles sejam um suporte no amadurecimento cristão daqueles que lhes foram confiados. Que tenham êxito na sua missão de introduzir as crianças na fé cristã através do testemunho, diálogo e vivência comunitária. Tudo isto te pedimos por Cristo Nosso Senhor. Amém.</p> <p>Ide em paz, que o Senhor vos acompanhe!</p> <h4>Material de Apoio</h4> <p>O símbolo da fé</p> <p><em>Das catequeses de São Cirilo de Jerusalém, Bispo. Séc. IV. (Cat. 5, De fide et symboli, 12-13: PG 33,519-523).</em></p> <p>Abraça, cuidadoso, unicamente a fé que agora a Igreja te entrega para aprendê-la e confessá-la, protegida pelos muros de toda a Escritura. Já que nem todos podem ler as Escrituras, uns por falta de preparo, outros por qualquer ocupação que os impede de conhecê-la, para que não pereçam por ignorância encerramos nos poucos versículos do símbolo todo o dogma da fé. Exorto-te a tê-lo como viático durante a vida inteira e não admitir nenhum outro mais. Nem se nós próprios, tendo mudado, dissermos algo contrário ao que ensinamos agora, nem mesmo se um anjo adverso, transfigurado em um anjo de luz, te quiser arrastar ao erro. Pois ainda que nós ou um anjo do céu vos anuncie coisa diferente do que agora recebestes, seja anátema (Gl 1,8).</p> <p>Ouves neste momento apenas simples palavras, mas guarda na memória o símbolo da fé. Em tempo oportuno receberás a confirmação de cada versículo tirado das Sagradas Escrituras. Porque não foi a bel-prazer dos homens que este resumo da fé foi composto, mas selecionados dentre toda a Escritura, os tópicos mais importantes perfazem e abraçam a única doutrina da fé. Da forma como a semente de mostarda num pequenino grão contém muitos ramos, assim este símbolo em poucas palavras encerra como num seio materno o conhecimento de toda a religião contida no Antigo e no Novo testamentos.</p> <p>Considerai, portanto, irmãos, e mantende as tradições que recebestes agora e gravai-as no fundo de vosso coração. Observai-as religiosamente, não aconteça que o inimigo em qualquer lugar venha a espoliar os covardes e negligentes, ou um herege alterar algo do que vos foi entregue. A fé é depositar no banco o dinheiro que vos confiamos. Mas Deus vos pedirá contas do depósito.</p> <p>Peço-vos, assim diz o Apóstolo, diante de Deus, que tudo vivifica, e de Cristo Jesus, que deu seu belo testemunho sob Pôncio Pilatos (1Tm 6,13), que conserveis imaculada esta fé entregue a vós, até que apareça nosso Senhor Jesus Cristo. Agora te foi dado o tesouro da vida. O Senhor exigirá seu depósito por ocasião de seu aparecimento, que no tempo preestabelecido o bem-aventurado e único Soberano, o Rei dos reis e Senhor dos senhores, manifestará. Ele, o único a possuir a imortalidade, que habita em luz inacessível, a quem ninguém jamais viu nem pode ver (1Tm 6,15-16). A Ele glória, honra e império pelos séculos dos séculos. Amém.</p>', preparo_html='<p>Prever sala mais ampla para acomodar todos os participantes. Nesta sala providenciar: ambão com toalha da cor do Tempo Litúrgico, Bíblia, vela e flores. Em uma mesa: folhas com o credo que serão entregues aos catequizandos (sugerimos colocar as duas versões do Credo, uma paralela a outra: O Credo dos apóstolos e o niceno-constantinopolitano) e cópias com o roteiro da celebração.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=2; -- Encontro de Preparação para a Celebração de Entrega do Símbo
update encontros set conteudo_html='<p><em>(Celebração a ser realizada em um dos domingos do Tempo do Advento).</em></p> <p><strong>Palavra inicial:</strong> Esta celebração tem o objetivo de apresentar a toda a comunidade os catequizandos que estão iniciando a segunda etapa da catequese, chamando a atenção para a grande importância desse processo para a vida da Igreja, bem como entregar-lhes a "Profissão de Fé". (lê-se do livro apenas o primeiro nome – nome de Batismo – se forem muitos pode-se omitir a leitura dos nomes).</p> <p><strong>Preparando o ambiente:</strong> Livro onde foi registrado os nomes dos catequizandos ao final da primeira etapa e envelopes com a folha contendo a Profissão de Fé (Credo), de preferência nas duas versões (dos apóstolos e o Credo niceno-constantinopolitano). Reservar bancos para os catequizandos e padrinhos. Preparar crachás para cada catequizando para que o padre saiba o nome de cada um na hora de entregar o Credo.</p> <p>Procissão inicial: Os catequizandos e padrinhos de Batismo participam da procissão inicial. Pode-se levar ainda o Livro de registro com os nomes dos catequizandos e os envelopes contendo a "Profissão de Fé".</p> <p>Saudação inicial: O presidente acolhe os catequizandos, familiares e padrinhos. (tudo segue como de costume, até a homilia).</p> <p>Após a homilia o presidente prossegue com a entrega da "Profissão de Fé", dirigindo-se aos catequizandos com estas palavras ou outras semelhantes:</p> <p>Presidente: Caríssimos catequizandos, agora vocês receberão e escutarão as palavras da fé pela qual vocês serão salvos. São poucas, mas contêm grandes mistérios. Recebam e guardem essas palavras com pureza de coração.</p> <p><em>(Podem se aproximar um de cada vez, ou, se forem muitos, fazem uma fila um ao lado do outro e o presidente faz a entrega do Símbolo impresso. Pode ter apenas uma música instrumental. Depois que todos receberam o presidente convida toda a comunidade a ficar de pé e começa o Símbolo dizendo:)</em></p> <p>Creio em Deus, (E continua sozinho ou com a comunidade dos fiéis) Pai todo-poderoso, criador do céu e da terra; e em Jesus Cristo, seu único Filho, nosso Senhor, que foi concebido pelo poder do Espírito Santo, nasceu da Virgem Maria, padeceu sob Pôncio Pilatos, foi crucificado, morto e sepultado; desceu à mansão dos mortos;</p> <p>Rito de entrega da "Profissão de Fé"</p> <p>Após a proclamação do Evangelho o diácono, ou na falta dele o catequista, pega o livro solenemente com os nomes dos catequizandos e chama-os cada um pelo nome.</p> <p>Diácono: Queiram aproximar-se os que estão com os nomes inscritos no livro dos catequizandos e que receberão da Igreja o Símbolo da fé: ... N..., ... N...</p> <p>Cada um responde individualmente: <em>Presente!</em> (ou todos juntos, se forem muitos).</p> <p>Adaptado do Ritual de Iniciação Cristã – RICA.</p> <p>A missa prossegue como de costume.</p> <p>Preces: Na "Oração da Assembleia" podem-se acrescentar algumas das orações:</p> <ul> <li><p>Para que esses catequizandos meditem e professem a fé cada dia em seus corações, roguemos ao Senhor;</p></li> <li><p>Para que os catequizandos, confiando e testemunhando a fé no Cristo e na Igreja, vivam na liberdade dos filhos de Deus, roguemos ao Senhor;</p></li> <li><p>Para que esses catequizandos, contemplando a sabedoria da cruz, possam gloriar-se em Deus, que confunde a sabedoria deste mundo, roguemos ao Senhor;</p></li> <li><p>Para que o Espírito Santo, que sonda os corações de todos, fortifique com sua força divina esses catequizandos e lhes ensine as coisas que são de Deus e a Ele agradam, roguemos ao Senhor;</p></li> <li><p>Para que a família desses catequizandos coloque sua esperança em Cristo e nele encontrem paz e santidade, roguemos ao Senhor;</p></li> <li><p>Para que as famílias e os povos impedidos de abraçar a fé tenham a liberdade de crer no Evangelho, roguemos ao Senhor;</p></li> <li><p>Senhor, fortaleça e ilumine todos os padrinhos e madrinhas de Batismo em sua missão de introduzir seus afilhados na fé cristã, roguemos ao Senhor.</p></li> </ul> <p>Presidente: Senhor, fonte da luz e da verdade, imploramos vosso amor de Pai em favor destes vossos servos: Purificai-os e santificai-os; dai-lhes verdadeira ciência, firme esperança e santa doutrina para que se tornem dignos do teu Reino. Por Cristo, Nosso Senhor.</p> <p><em>Todos rezam em silêncio. Quem preside continua com as mãos estendidas sobre os catequizandos:</em></p> <p>Presidente: Oremos pelos nossos catequizandos: que o Senhor nosso Deus abra os seus corações e as portas da misericórdia para que assumam com amor a fé no Cristo e sejam verdadeiros discípulos missionários do seu Reino.</p> <p><em>Quem preside diz, com estas palavras ou outras semelhantes:</em></p> <p>Diácono: Prezados catequizandos, ajoelhem-se para a oração sobre vocês.</p> <p><em>O diácono ou outro ministro ou ainda o próprio catequista convida os catequizandos a se ajoelharem, dizendo:</em></p> <p>Creio no Espírito Santo, na santa Igreja Católica, na comunhão dos santos, na remissão dos pecados, na ressurreição da carne, na vida eterna. Amém.</p> <h4>Observação</h4> <p>Aconselhamos que essa celebração aconteça em um dos domingos do Tempo do Advento. Porém, por motivos pastorais pode ocorrer num outro dia.</p>', preparo_html='<p>Livro onde foi registrado os nomes dos catequizandos ao final da primeira etapa e envelopes com a folha contendo a Profissão de Fé (Credo), de preferência nas duas versões (dos apóstolos e o Credo niceno-constantinopolitano). Reservar bancos para os catequizandos e padrinhos. Preparar crachás para cada catequizando para que o padre saiba o nome de cada um na hora de entregar o Credo.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=3; -- Celebração de Entrega do Credo
update encontros set conteudo_html='<p><em>(Encontro a ser realizado na 1ª SEMANA DO ADVENTO).</em></p> <p><strong>Palavra inicial:</strong> Neste primeiro encontro o objetivo é fazer uma retrospectiva da temática central (querigma), abordado nos encontros da primeira etapa, além de fazer uma avaliação com catequizandos que os catequizandos percebam que estão vivendo numa nova etapa do processo catequético do qual lhes serão apresentados os conteúdos de nossa fé, professados no "Símbolo da Fé".</p> <p><strong>Preparando o ambiente:</strong> Ambão com toalha roxa, vela, flores e Bíblia. Para a dinâmica: revistas velhas que possam ser recortadas, tesoura sem ponta, cola, cartolina e uma imagem pequena de Jesus (se possível do Bom Pastor).</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos, saudando-os com a frase: "Seja bem-vindo... N..., Cristo está contigo!" Pede para que se assentem nas cadeiras ao redor da mesa. Quando já estiverem na sala, saúda a todos mais uma vez, desejando-lhes boas-vindas, que poderá ser com um canto.</p> <p><strong>Recordação da vida:</strong> Logo após a acolhida, ao redor da Mesa da Partilha, ou em pé ao redor da Mesa da Palavra, em clima de oração que pode ser proporcionado por um refrão meditativo, convidar os catequizandos a fazer uma retrospectiva de como foi participar da primeira etapa da catequese. O que sentiram e como participaram da "celebração de inscrição do nome e entrega do Livro". Perguntar se todos estão lendo a Bíblia em casa e em família.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> Após a recordação da vida, o catequista inicia a oração, colocando como intenção todos os fatos recordados pelos catequizandos. Poderá iniciar ou concluir com a oração sugerida, ou de preferência com uma oração espontânea:</p> <p>Senhor Jesus, novamente estamos aqui para conhecê-lo melhor e fazer uma experiência viva consigo. Queremos entender a mensagem de Amor do Pai que nos quer transmitir. Que sejamos firmes e perseverantes como seus discípulos no anúncio da sua Palavra.</p> <p>O catequista dirige-se até o ambão e proclama o texto indicado.</p> <p><strong>Leitura do texto bíblico:</strong> Ez 34,11-12.15-16a.</p> <p>Em seguida, após alguns minutos de silêncio, lê-o novamente, desta vez pausadamente, destacando alguns pontos: <em>"[...] eu mesmo buscarei minhas ovelhas e tomarei conta delas [...] procurarei a ovelha perdida..."</em> Todos retornam para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>O catequista reconstrói o texto com os catequizandos. Deixar que os catequizandos falem sobre o texto que acabaram de ouvir. Caso seja necessário, algumas perguntas poderão incentivá-los a participar: O que o pastor vai fazer? Para onde irá levar o rebanho? Quem é o pastor para nós? Depois conta a história "O livro dá hora".</p> <p>Antes o catequista poderá fazer uma recordação dos personagens e do final da última história contada na 1ª etapa da catequese. Segue alguns dados para ajudar:</p> <p>Passados vinte anos, novamente na véspera de Natal, Amanda era casada com Leonardo e tinha uma filha, Isabel. Amanda naquele ano era catequista e responsável pela encenação do nascimento de Jesus. Fernando era casado com Dora, e tinha filhos gêmeos, Otávio e Leandro. Fernando havia se tornado músico e era vocalista de uma banda de música católica. E Pedrinho havia se tornado padre, agora Padre Pedro.</p> <p>Neste novo ciclo de histórias que se inicia, os filhos de Amanda e de Fernando e o Padre Pedro serão os personagens centrais. Como no início das histórias do Livro da 1ª etapa, as crianças iriam encenar na véspera de Natal o nascimento do Menino Jesus: Otávio seria José e Leandro o Anjo Gabriel e Isabel seria Maria, a mãe de Jesus. Antes do teatro começar, Padre Pedro foi levar as crianças para tomar água, e acabaram tropeçando em latas de tintas, com o susto que tiveram com os relâmpagos que faziam por causa da tempestade. Naquele ano a igreja estava passando apenas por uma pintura. Padre Pedro e as crianças caíram numa sala escura...</p> <p>O livro "dá hora"</p> <p>Relampejava muito e os trovões eram cada vez mais altos. Padre Pedro continuava desacordado.</p> <p>– Otávio! A gente precisa chamar alguém pra ajudar o padre! – disse Leandro, que estava vestido de anjinho.</p> <p>– Gente, olha só o tamanho daquele livro! – exclamou Otávio ao ver, com a ajuda dos relâmpagos, um livro muito grande, maior que eles, encostado à parede.</p> <p>– Nossa! Parece uma Bíblia gigante! – disse Isabel.</p> <p>Os três se aproximaram da Bíblia encostada à parede. Isabel chegou mais perto e foi logo querendo abri-la, mas Otávio segurou sua mão.</p> <p>– Não, Isabel!</p> <p>– Ah, por que não posso abrir? – e ela abriu a Bíblia. Um clarão saído da Bíblia iluminou todo aquele lugar. A figura que viam parecia ser tão real que do outro lado até viam um cachorrinho correndo.</p> <p>– Que livro "dá hora"! O desenho do cachorrinho até se mexe – disse Leandro.</p> <p>– Ele tá triste, parece perdido – disse Otávio. E o cachorrinho agora parecia que tinha os visto e vinha na direção deles. Otávio, que adorava bichos, logo tratou de ir ao encontro do cãozinho. Isabel e Leandro não acreditaram que Otávio tinha entrado naquela grande Bíblia.</p> <p>– Como que o meu irmão fez isso? – perguntou Leandro.</p> <p>Isabel apenas pegou sua mão e os dois foram para o outro lado também. O cãozinho que era de cor caramelo fazia a maior festa com a presença dos três ali. Quando lembraram que tinham entrado na Bíblia, já era tarde demais, pois não viam a sala escura do outro lado. Eles se apavoraram e corriam de um lado para o outro, mas em vão, não achavam um meio de retornar. Otávio começou a chorar agarrado ao cachorrinho.</p> <p>– Para de chorar, Otávio! Senão eu também vou chorar... – disse Leandro, ao irmão gêmeo.</p> <p>– Não vai adiantar a gente ficar aqui chorando. A gente tem que procurar ajuda pra voltar pra casa.</p> <p>– É mesmo, Isabel. Quem sabe o dono do cachorrinho perdido não ajude a gente.</p> <p>– Ah não! Eu quero ficar com ele pra mim.</p> <p>– Aí, vamos achar um jeito de sair logo daqui vai, depois a gente vê o que faz com esse cachorro.</p> <p>E os três saíram sem rumo. Andaram muito, assim como seus pais um dia também andaram, procurando o caminho de volta para casa. Otávio começou a chorar e Leandro o abraçou para consolar o irmão.</p> <p>– Pode parar de chorar, Otávio. Quem veio parar aqui primeiro foi você! E cadê a fé em Deus? Vai me falar que você não tá acreditando que uma hora a gente vai voltar pra casa.</p> <p>– Não sei... Não sei, Isabel – respondeu Otávio soluçando. O cãozinho, parecendo entender a tristeza de Otávio, lambeu sua bochecha.</p> <p>– A minha mãe, toda vez que tá com problema, que discute com o meu pai, quando fica triste porque alguma coisa que ela queria que não acontecesse aconteceu, ela escuta uma música da Adriana, que fala assim: por que tenho medo? Se nada é impossível para ti? Se nada é impossível para ti. Por que tenho medo, se nada é impossível para ti... Nada é impossível para ti. Então, não precisa ter medo, nem ficar triste, nem duvidar, porque Deus vai ajudar a gente. Uma hora vai aparecer alguém que vai ajudar a gente voltar pra casa.</p> <p>E Isabel abraçou os gêmeos.</p> <p>– Deus é bom que nem o nosso pai é pra gente, Otávio. Ele vai cuidar da gente e não vai deixar nenhum mal acontecer.</p> <p>– Eu sei que Deus tá sempre com a gente... Que Ele nos vê e nos ouve... Mas eu tenho medo de não voltar e não ver o papai e a mamãe nunca mais.</p> <p>– A gente não devia ter entrado na Bíblia. Agora a gente vai ter que aguentar e seguir em frente. Vai, vamos logo que tá começando a ficar escuro, e eu tenho medo de escuro.</p> <p>– Ahhhhh... aí, você também tem medo, viu? Medrosa!</p> <p>– Para de graça, Otávio! É um medo diferente!</p> <p>E os três seguiram em frente em busca de alguém que os ajudasse a voltar pra casa.</p> <p>Após a história, desenvolver o tema com os catequizandos, abordando a segurança que Jesus nos oferece. Que Ele nunca nos deixa sós. Pelo contrário, nós que nos desgarramos muitas vezes do rebanho. Como é bom termos essa certeza. Por mais difícil que seja o caminho, Jesus caminha conosco!</p> <p><strong>Dinâmica:</strong> Distribuir aos catequizandos várias revistas que possam ser recortadas. Pedir para recortarem imagens que representem pessoas (qualquer estilo). Após todos recortarem (poderá ser mais de uma imagem por catequizando), o catequista deverá colar essas imagens em uma cartolina, formando um círculo e deixando o centro livre.</p> <p>Avaliar com os catequizandos nas imagens recortadas: quem são as pessoas, como estão vestidas, o que representam. Nesse momento deixar os catequizandos falarem. Verificar a diversidade: são pessoas diferentes e que nem se conhecem. Porém, verificamos que o centro do desenho está vazio.</p> <p>Existe alguém que fez uma promessa: <em>"cuidarei de minhas ovelhas e as resgatarei de todos os lugares [...] Eu mesmo apascentarei minhas ovelhas e as farei repousar"</em> (Ez 34,12.15).</p> <p>Perguntar: Quem é essa pessoa?</p> <p>Nesse momento o catequista cola no centro a imagem de Jesus.</p> <p>Após colar a imagem o catequista pergunta por que Jesus está no centro. Poderá dizer depois os comentários dos catequizandos que Jesus é o centro da nossa vida, sem Ele, por mais que estejamos juntos com outras pessoas, existirá um vazio que só Ele pode preencher. As pessoas diferentes nos ajudam a compreender a passagem bíblica lida, que Jesus reunirá ovelhas de "todos os lugares", sem distinção. Onde ninguém é maior ou melhor que o outro. Todos somos irmãos em Cristo, pertencemos ao mesmo rebanho, à mesma família.</p> <p>Em nossos encontros temos sempre essa certeza. Estamos reunidos, porém em seu nome. É Ele o motivo principal de estarmos aqui.</p> <p><strong>Conclusão:</strong> O encontro poderá ser concluído, pedindo para que os catequizandos levem essa mensagem a outras pessoas. Principalmente aos catequizandos que não vieram participar do primeiro encontro. Incentivá-los a irem visitá-los, dizendo que eles fazem parte deste rebanho e que estão fazendo muita falta. Também fazer o propósito de quando encontrarem alguém triste ou se sentindo sozinho, lembrar essa pessoa que Jesus está com ela, como Ele mesmo disse.</p> <p><strong>Oração final:</strong> O catequista convida os catequizandos a ficarem em pé ao redor da Mesa da Palavra e incentiva-os a fazer preces pedindo pela família, comunidade e amigos. Todos respondem no final de cada invocação: "Senhor, escuta a nossa prece".</p> <p>Concluir com o Pai-nosso e com a oração:</p> <p>Senhor Deus, obrigado pela certeza de estares junto conosco e nos acompanhar. Pedimos por todos aqueles que ainda não te conhecem e por isso se sentem sozinhos. Que o Senhor ampare e conforte a todos. Por Cristo Nosso Senhor. Amém.</p> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo: "...N... vai em paz, que o Senhor te acompanhe! Amém".</p> <h4>Observação</h4> <p>Nesta etapa, os catequizandos já tiveram contato com a Bíblia e já a receberam solenemente. Portanto, nos próximos encontros serão eles que farão as leituras bíblicas. Seria importante fazer uma escala e distribuir com antecedência a passagem a ser lida para que o catequizando possa "treinar" a sua leitura. Incentive-os a fazer desta preparação um momento de oração. Pedir para que cheguem com antecedência, para que possam marcar a leitura na Bíblia utilizada nos encontros. Pedir para que todos tragam a Bíblia que receberam na celebração de entrega do Livro.</p> <h4>Dica</h4> <p>O catequista poderá propor fazer uma escala com os catequizandos, onde a cada encontro um ficará responsável de trazer flores para ornamentar o espaço da Palavra (poderá ser a mesma escala da leitura do texto bíblico).</p> <p>Além disso, recordamos a sugestão dada na primeira etapa, onde a cada semana um catequizando levará para casa a imagem de Nossa Senhora ou padroeiro da comunidade, na qual será incentivado a rezar em família.</p>', preparo_html='<p>Ambão com toalha roxa, vela, flores e Bíblia. Para a dinâmica: revistas velhas que possam ser recortadas, tesoura sem ponta, cola, cartolina e uma imagem pequena de Jesus (se possível do Bom Pastor).</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=4; -- A História Continua
update encontros set conteudo_html='<p><em>(Encontro a ser realizado na 2ª SEMANA DO ADVENTO)</em></p> <p><strong>Palavra inicial:</strong> Querido catequista, a partir deste encontro iremos apresentar aos catequizandos o Credo, do qual iremos refletir uma parte a cada encontro. Neste encontro começaremos com a frase: "Creio em Deus Pai todo-poderoso", mostrando que o ato de crer, de acreditar, nasce da fé em um Deus que é todo-poderoso, e que se revelou à humanidade.</p> <p><strong>Preparando o ambiente:</strong> Ambão com toalha roxa, vela, flores, cartaz grande com a Profissão de Fé e cópias da oração para ser distribuída no final do encontro para cada catequizando.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos, saudando-os com a frase: "...N..., Deus conhece a cada um de nós!", ou outra semelhante. Quando já estiverem na sala, saúda a todos mais uma vez, desejando-lhes boas-vindas e convida-os a se dirigirem até a Mesa da Partilha.</p> <p><strong>Recordação da vida:</strong> Após serem acolhidos, farão uma retrospectiva da semana, e o catequista poderá perguntar sobre o encontro anterior, relembrando-o.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> O catequista inicia a oração valorizando todas as coisas ditas na recordação da vida. Convida-os a juntos rezarem o Credo. No final pode-se rezar a oração:</p> <p>Senhor, obrigado(a) por estarmos novamente reunidos em vosso nome. Fazemos o propósito de conhecer-vos melhor para vos servir e louvar. Somos agradecidos ao Pai, que no seu plano de Amor vos enviou para que possamos conhecer a Boa-Nova.</p> <p>O catequista convida o catequizando escalado como leitor do encontro para se dirigir até o ambão e proclamar o texto indicado.</p> <p><strong>Leitura texto bíblico:</strong> Êx 3,6-9.</p> <p>Em seguida, após uns minutos de silêncio, o catequista o lê novamente, desta vez pausadamente, destacando alguns pontos do texto.</p> <p>"[...] Eu sou o Deus de teu pai [...]. Eu vi a opressão do meu povo no Egito, ouvi seus gritos [...] tomei conhecimento de seus sofrimentos".</p> <p>Após a leitura, todos dirigem-se para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>Pedir aos catequizandos para que reconstruam o texto bíblico. Deixar que falem. Depois pedir aos catequizandos para abrir suas bíblias na passagem proclamada na Mesa da Palavra, e os convida a uma leitura silenciosa observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar. É importante o catequista NÃO dizer a página em que se encontra a passagem bíblica, mas sim orientá-los como procurar as citações.</p> <p>Logo após contar a história "Deus ouve nossa oração".</p> <p>Deus ouve nossa oração</p> <p>As crianças caminhavam com fome procurando alguém que as ajudasse a voltar para casa. O cachorrinho, que tinha recebido o nome de Totó, ia junto ao colo de Otávio. Eles estavam tão cansados e com tanta fome que Leandro sugeriu que se sentassem um pouco. Isabel disse que precisavam caminhar mais, pois já estava quase à noitinha e eles não tinham encontrado um lugar seguro para passarem a noite. Eles pararam embaixo de uma árvore de galhos grandes e grossos.</p> <p>– Bem que as asinhas do meu figurino podiam ser de verdade e, assim, eu poderia voar bem alto e ver onde é que têm pessoas para ajudar a gente – disse Leandro, que no Auto de Natal seria o Arcanjo Gabriel.</p> <p>E para surpresa das crianças as asinhas de Leandro começaram a bater e ele começou a subir sozinho pelo ar.</p> <p>– Uau! E não é que Deus ouviu o meu pedido e realizou esse milagre! – e Leandro voou bem alto e lá de cima ele via o sol se pôr no horizonte se escondendo em meio às montanhas.</p> <p>– Você tá vendo alguma casa ou alguma pessoa? – perguntou Otávio, que colocava Totó ao chão.</p> <p>Leandro não viu ninguém. Eles, então, se abrigaram numa pequena caverna ao pé de uma montanha, esperando que no dia seguinte pudessem voltar para casa. Isabel sugeriu que eles rezassem para agradecer a Deus pelo milagre, porque mesmo que naquele momento eles não tivessem encontrado alguém, no dia seguinte Leandro poderia voar e encontrar.</p> <p>– Eu lembro que a minha mãe disse um dia que Deus sempre ouve a nossa oração, e que a gente tem que saber esperar, porque na hora certa o milagre acontece!</p> <p>Após a história, interrogar os catequizandos sobre o significado da palavra CRER (Deixar falarem). Explicar que, segundo o Dicionário Aurélio (2. ed., 1988), crer significa: Acreditar; ter por certo ou verdadeiro. Aceitar como verdadeiras as palavras de. Ter fé, dar crédito. Crer, acreditar é algo que nasce da fé em um Deus que se apresenta como Pai e do qual nós não podemos ver, mas o sentimos. Esclarecer que na Profissão de Fé, iniciamos com essa frase: "Creio em Deus Pai, todo-poderoso". Nessa oração professamos que Deus é Pai e que possui poder. Contar aos catequizandos que Deus se apresenta a Moisés (o catequista poderá falar um pouco sobre quem foi Moisés), dizendo que ouve a aflição de seu povo. Quando falamos ao telefone com alguém que nós não o vemos, mas sabemos que ela existe, está nos ouvindo e fala conosco. É como quando nós rezamos. Nós não podemos ver a Deus, mas a Bíblia conta-nos que, quando falamos com Deus, Ele nos ouve cuidadosamente. Nós podemos contar-lhe todas as nossas coisas. Conversar sobre o fato de que acreditar, ter fé é um ato pessoal, onde o fiel submete completamente sua inteligência e vontade a Deus. É aceitar livremente toda a verdade que Deus revelou ao homem. E isso implica uma adesão pessoal, um comprometimento com Deus e a Igreja, a colocar em prática e a viver os seus mandamentos. Apesar disso, da fé ser um ato pessoal, de forma alguma é um ato isolado. Ninguém pode crer sozinho ou dar a si próprio a fé. Recebemos a fé da Igreja, a professamos e a transmitimos. Quando digo "eu creio", professo de maneira pessoal a fé recebida, ao passo que os fiéis reunidos numa mesma fé, em comunidade, dizem "nós cremos". Nos artigos 166 e 167 do Catecismo da Igreja Católica (CIC) podemos ler: "A fé é um ato pessoal: a resposta livre do homem...</p> <p>à iniciativa de Deus que se revela à humanidade. Ela não é, porém, um ato isolado. Ninguém pode crer sozinho, assim como ninguém pode viver sozinho. Ninguém deu a fé a si mesmo, assim como ninguém deu a vida a si mesmo. Recebemos a fé de outros, e devemos anunciá-la a outros. Nosso amor por Jesus e pela Igreja nos impulsiona a falar a outros de nossa fé. Cada pessoa que crê é como um elo na grande corrente dos crentes. Não posso crer sem ser carregado pela fé dos outros, e pela minha fé contribuo para carregar e alimentar a fé dos outros. "Eu creio": esta é a fé da Igreja, professada pessoalmente por todo crente, principalmente pelo batismo. "Nós cremos": esta é a fé da Igreja professada pelos bispos reunidos em Concílio ou, mais comumente, pelos fiéis reunidos para celebrar a Eucaristia. "Eu creio": é também a nossa Mãe Igreja, que responde a Deus com sua fé e que nos ensina a dizer: "eu creio", "nós cremos".</p> <p>Explorar que "Profissão de Fé", "Credo" e "Símbolo de Fé", são os nomes conhecidos com que costumamos nos referir aos textos que resumem e traduzem o essencial daquilo que nós cristãos católicos acreditamos. "Credo" porque é uma palavra do latim que significa "creio", primeira palavra que recitamos na fórmula da fé. Orientar que a Igreja sempre pelos séculos procurou preservar e propagar a fé recebida. Na catequese somos convidados a refletir sobre o que acreditamos, sobre a nossa fé, somos convidados a alicerçá-la para que assim como aqueles que vieram antes de nós, a viveram e a propagaram, a ponto de chegar até os nossos dias, nós também, devemos vivê-la e anunciá-la às futuras gerações. Ajudar os catequizandos a compreender que, hoje, se estamos participando da catequese e das atividades de nossa Igreja é porque nossos pais acreditaram, e nós também, como filhos e filhas do único Deus, queremos professar e propagar a fé professada por toda a nossa Igreja. Por fim dizer que Deus é "Pai" e é "todo-poderoso" porque a sua paternidade e poder é caracterizado por uma liberdade amorosa e paterna. Deus é pai, pois em Jesus e com sua morte e ressurreição, nos adota como filhos e filhas, e com seu poder criador e salvador, respeita nossa liberdade e nos chama constantemente ao seu Reino (o céu). O seu poder é o amor e a misericórdia.</p> <p><strong>Conclusão:</strong> Hoje, aprendemos um pouco mais sobre o que é "crer". Vimos que a fé é algo pessoal, porém que deve ser vivida comunitariamente. E que Deus está sempre presente conosco e nos ouve. E nós, temos ouvido a Ele também? Estamos praticando a sua vontade? Temos ouvido as outras pessoas, ou só estamos preocupados conosco mesmos? Pois, como vimos, não podemos crer sem ser carregados pela fé dos outros. Quantas vezes ouvimos testemunhos belíssimos de nossos irmãos e de santos que nos alegram e nos animam e nos fortalecem na caminhada? Nosso compromisso é estarmos atentos às nossas ações, se elas estão sendo coerentes com a vontade do Pai, além de aprendermos a ouvir mais as pessoas, procurando entendê-las e enxergar as ações de Deus em suas vidas.</p> <p>O catequista orienta os catequizandos a levarem para casa a cópia da Profissão de Fé que receberam e a colar no Diário Catequético e Espiritual e a fazer as atividades propostas no diário.</p> <h4>Observação</h4> <p>Sugerimos que os catequizandos recebessem o Credo impresso contendo as duas versões: O "Símbolo dos Apóstolos" e o Credo "niceno-constantinopolitano". Para os encontros de catequese usamos os artigos do Símbolo dos Apóstolos, por ser mais resumido e de mais fácil compreensão, porém o catequista poderá usar do Credo niceno-constantinopolitano para acrescentar e enriquecer os encontros, bem como a sua formação pessoal. No final de alguns encontros, colocamos no material de apoio, os artigos correspondentes do Credo niceno-constantinopolitano.</p> <h4>Material de apoio</h4> <ul> <li><p>Aprofundar o tema nos parágrafos 26 a 73 e 185 a 278 do Catecismo da Igreja Católica.</p></li> <li><p>No Símbolo niceno-constantinopolitano: "Creio em um só Deus, Pai todo-poderoso..."</p></li> </ul> <p>"Vai em paz, ...N..., filho amado do Pai!" No final da oração o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo:</p> <p>Ó Deus, somos agradecidos por poder contar-lhe todas as coisas. Como Pai zeloso, sempre nos ouve e quer nos ajudar. Obrigado por ouvir-nos. Ajude-nos a ouvi-lo também. Por Cristo Nosso Senhor. Amém.</p> <p><strong>Oração final:</strong> O catequista convida os catequizandos a ficarem em pé ao redor da Mesa da Palavra. Incentiva os catequizandos a formularem orações e preces e conclui com a oração:</p>', preparo_html='<p>Ambão com toalha roxa, vela, flores, cartaz grande com a Profissão de Fé e cópias da oração para ser distribuída no final do encontro para cada catequizando.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=5; -- Creio em Deus Pai todo-poderoso
update encontros set conteudo_html='<p><em>(Encontro a ser realizado na 3ª SEMANA DO ADVENTO)</em></p> <p><strong>Palavra inicial:</strong> Prezado catequista, queremos neste encontro refletir com os catequizandos que Deus é o autor de toda criação. Não queremos ver o texto bíblico com um olhar literal, mas buscando a mensagem que o autor quis deixar ao escrever a história da criação: A intenção não foi escrever como o mundo foi criado, mas dizer que tudo o que existe é criação do único e verdadeiro Deus. Além disso, queremos ensinar os catequizandos a serem agradecidos por toda obra criadora, fazendo-os reconhecer em todas as coisas existentes a manifestação de Deus.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha roxa, vela e 2 cartazes representando a natureza. Um cartaz com imagem do céu, estrelas, lua, planetas (noite). Outro cartaz com imagem do céu, sol, nuvens, água, flores, animais e pessoas (dia). Para a dinâmica: folhas de sulfite e lápis de cor ou giz de cera.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos saudando-os e conduzindo-os para a sala de encontro: "Seja bem-vindo ...N..., criação perfeita de Deus".</p> <p><strong>Recordação da vida:</strong> Após serem acolhidos, ao redor da Mesa da Partilha ou da Mesa da Palavra, em clima de oração, fazer uma retrospectiva da semana, e o catequista poderá perguntar sobre o encontro anterior, pedindo para que partilhem o que cada um experienciou. Poderão destacar ainda, os acontecimentos importantes que possam ter ocorrido na vida da comunidade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> O catequista conduz a oração inicial e por fim convida a todos a rezar o "Credo" e conclui com a oração:</p> <p>Senhor Nosso Pai, estamos aqui reunidos para conhecermos mais sobre ti e reconhecermos que tudo foi feito por ti, e sem ti nada do que foi criado poderia ser feito. Envia sobre nós o teu sopro criador, o Espírito Santo, para que possamos compreender todo o seu projeto de salvação. Amém.</p> <p>O catequizando escalado como leitor do encontro se aproxima do ambão e proclama o texto indicado.</p> <p><strong>Leitura do texto bíblico:</strong> Gn 2,4b-7.</p> <p>Após um período de silêncio o catequista lê novamente o texto, desta vez pausadamente, destacando alguns pontos do texto.</p> <p>"No dia em que o SENHOR Deus fez a terra e o céu [...] Deus formou o ser humano do pó da terra, soprou-lhe nas narinas o sopro de vida e ele tornou-se um ser vivo".</p> <p>Todos se dirigem até a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>Reconstruir o texto bíblico com os catequizandos. Depois o catequista questiona-os: Quais as coisas que foram criadas por Deus? Deixar os catequizandos falarem. Depois pedir aos catequizandos para abrir suas bíblias na passagem proclamada na Mesa da Palavra, e os convida a uma leitura silenciosa observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar. Depois contar a história "Louvado seja Deus por todas as suas criaturas", mostrando que tudo que existe é criação de Deus.</p> <p>Louvado seja Deus por todas as suas criaturas</p> <p>No dia seguinte nossos amiguinhos, Isabel e os gêmeos Otávio e Leandro, acordaram com um pouco de dor nas costas por terem dormido no chão. Mas a vontade de voltar para casa era tão grande que logo se esqueceram das dores e saíram da caverna para acharem algo de comer. Eles entraram no meio de uma floresta e logo viram uma macieira. Isabel adorava comer maçã. Eles apanharam algumas e depois as lavaram num riacho que corria por ali de águas cristalinas.</p> <p>– Será que essa água tá limpa mesmo?</p> <p>– Claro que tá, Leandro! Não tá vendo o fundo do riacho? – disse Otávio.</p> <p>– Ah, mas sei lá... é difícil de acreditar que ainda tenha riachos, córregos e rios de água limpa.</p> <p>– O Leandro tem razão. Todo mundo, até mesmo a gente, polui o meio ambiente mesmo sem perceber. A gente descasca uma bala ou um chiclete e faz o que, se tá na rua? Joga no chão!</p> <p>– Nossa, é verdade! A gente faz isso mesmo sem perceber...</p> <p>– Pois é, Leandro! A gente esquece que, se chove, a enxurrada vai levar toda a sujeira que a gente joga na rua pro bueiro e depois pode ir parar num córrego, num riacho ou rio...</p> <p>– Imagina se um peixe ou outro bichinho que vive na água engolir um papel de bala... – disse Otávio – pode morrer.</p> <p>– Se a gente se lembrasse mais que tudo que existe na natureza foi criado por Deus com tanto amor, a gente ia cuidar mais do nosso planeta.</p> <p>– Um dia meu pai falou que esse monte de tempestade é a natureza que tá cansada de ser tão maltratada e por isso tá ficando nervosa e fazendo essas coisas.</p> <p>– Minha mãe disse a mesma coisa, Lê! – disse Isabel, mordendo uma maçã.</p> <p>– Seria tão legal se tivesse mais lugares assim como esse pra gente visitar, né? Olha quantas árvores... essa água doce limpinha. Olha lá do outro lado! Tem coelhinhos! – apontou Otávio.</p> <p>– E tem macacos nas árvores olhando pra gente também! – exclamou Isabel.</p> <p>– Louvado seja Deus por toda a sua criação e por ainda existir um lugar tão bonito e tão cheio de bichos como esse! – rezou Otávio, segurando Totó nos braços.</p> <p>Após a história, recolher os cartazes que estavam no ambão e apresentar aos catequizandos. Mostrar-lhes algumas obras criadas por Deus. Depois questioná-los se eles sabem como que tudo isso foi criado. Se realmente foi como está descrito na Bíblia, principalmente quanto à criação do homem. Deixar que eles falem. Depois, se possível aproveitando as falhas dos catequizandos, explicar-lhes que existem várias teorias da "história da criação", de como o mundo surgiu. Refletir que não sabemos ao certo como foi, pois nenhum de nós estava lá. Só podemos afirmar que a única certeza que temos é de que foi Deus quem criou tudo. Não sabemos como, se foi do barro, se foi pela palavra, ou de outra maneira. A história narrada na Bíblia, no Livro de Gênesis, não quer nos dizer como o mundo foi criado, mas quer transmitir uma mensagem para todos aqueles que não acreditavam no Deus único. Na época em que o Livro de Gênesis foi escrito havia várias pessoas que acreditavam que o sol, a lua, a terra, o trovão, eram deuses. Então o autor bíblico escreve essa história para dizer que tudo aquilo que o povo dizia que era deus, na verdade era criação do único Deus, nosso Pai. Deus criou o mundo, a natureza e a cada um de nós. Ao criar o mundo, Deus o confiou ao homem, para que dele usufruísse e cuidasse. O catequista, recordando a história, poderá questionar os catequizandos se eles têm cuidado em preservar a obra criadora de Deus.</p> <p><strong>Dinâmica:</strong> Distribuir folhas de sulfite para os catequizandos e pedir para que eles desenhem outras coisas que não estão nos cartazes e que foram criadas por Deus. Socializar os desenhos com todos os catequizandos. Enquanto a atividade é desenvolvida o catequista poderá colocar uma música com som de barulhos de água, pássaros...</p> <p><strong>Conclusão:</strong> Vimos que o Senhor Deus é o autor de todas as coisas. Ele é o princípio e o fim de toda a criação. Vamos refletir juntos: Será que damos o devido valor e gratidão a todas as coisas criadas por Ele? Ou será que ainda procuramos outros deuses que possam nos oferecer outras obras? (deus do dinheiro, deus do poder, ganância, drogas, entre outras coisas).</p> <p><strong>Oração final:</strong> O catequista convida os catequizandos a ficarem em pé ao redor da Mesa da Palavra, onde inicia agradecendo a Deus por algumas coisas e pede aos catequizandos para que possam dar continuidade, fazendo outros agradecimentos.</p> <ul> <li><p>Obrigado pelo dom da vida...</p></li> <li><p>Obrigado por cada amanhecer...</p></li> <li><p>Obrigado pela água que me despertou, pelo sabonete perfumado, pela pasta de dente refrescante...</p></li> <li><p>Obrigado pela roupa que me veste, pelas cores que ela tem...</p></li> <li><p>Obrigado pela comida que me sustenta e pelo copo-d''água que mata a minha sede.</p></li> <li><p>Obrigado, Senhor...</p></li> </ul> <p>Logo após os agradecimentos espontâneos dos catequizandos o catequista conclui com a oração:</p> <p>Senhor, Deus Pai criador, nós agradecemos por ser o Senhor da Vida e autor de todas as coisas. Como filhos, prometemos ser obedientes e enxergar em cada criatura e criação o seu ato de amor por nós. Por Cristo Nosso Senhor. Amém.</p> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo: "...N..., criatura perfeita do Pai, vai em paz, e que o Senhor te acompanhe!"</p> <h4>Material de apoio</h4> <ul> <li><p>Aprofundar o tema nos parágrafos 279 a 421 do Catecismo da Igreja Católica (CIC).</p></li> <li><p>No Símbolo niceno-constantinopolitano: "...criador de todas as coisas visíveis e invisíveis...".</p></li> </ul>', preparo_html='<p>Ambão com toalha roxa, vela e 2 cartazes representando a natureza. Um cartaz com imagem do céu, estrelas, lua, planetas (noite). Outro cartaz com imagem do céu, sol, nuvens, água, flores, animais e pessoas (dia). Para a dinâmica: folhas de sulfite e lápis de cor ou giz de cera.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=6; -- Criador do céu e da terra
commit;
